 * @return an edge from the current node to the next node
 */
Edge edgeToNext() {
    // Check if the current node is virtual
    if (this.isVirtual()) {
        // If the current node is virtual, return the edge that connects it to its real counterpart
        return this.getRealNode().getEdgeToNext();
    }

    // Check if the next node is virtual
    if (this.getNextNode().isVirtual()) {
        // If the next node is virtual, return the edge that connects it to its real counterpart
